// Reusable reactive behavior extracted once, used everywhere.
import { customRef } from 'vue'

export function debouncedRef(value: string, delay = 300) {
  let timer: ReturnType<typeof setTimeout>
  return customRef((track, trigger) => ({
    get() {
      track()
      return value
    },
    set(newValue: string) {
      clearTimeout(timer)
      timer = setTimeout(() => {
        value = newValue
        trigger()
      }, delay)
    }
  }))
}
